// Oeste TextLink — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/text-link

const FOCUS = "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--color-ink)]";

export function TextLink({ href, children }) {
  return (
    <a href={href} className={"text-[15px] font-bold leading-[1] text-[var(--color-ink)] no-underline border-b-2 border-[var(--color-border)] pb-[1px] " + FOCUS}>{children}</a>
  );
}
